import importlib
import inspect
import unittest

# Generated by CMake from Tests_SRCS in CAM/CMakeLists.txt
# This replaces a previous implementation that used globbing to find test files. The
# CMake-generated version is an improvement because it ignores stale python files that
# globbing would detect and execute as if they were current tests.
import CAMTests.cam_test_modules

_EXCLUDE_MODULES = {
    "TestLinuxCNCLegacyPost",
    "TestGrblLegacyPost",
    "TestPathToolBitBrowserWidget",
    "TestPathToolBitEditorWidget",
    "TestPathToolBitListWidget",
    "TestPathToolBitPropertyEditorWidget",
    "TestPathToolDocumentObjectEditorWidget",
}

_EXCLUDE_MEMBERS = {
    "TestMachine": ["TestOutputOptions"],
    "TestPathToolAssetStore": ["BaseTestPathToolAssetStore"],
    "TestPathToolBitSerializer": ["_BaseToolBitSerializerTestCase"],
    "TestPostToolProcessing": ["TestEmptyMoveSuppression"],
}


def _load_cam_tests():
    for module_name in CAMTests.cam_test_modules.MODULES:
        if module_name in _EXCLUDE_MODULES:
            continue
        module = importlib.import_module(f"{__name__}.{module_name}")
        for name, obj in inspect.getmembers(module, inspect.isclass):
            if name in _EXCLUDE_MEMBERS.get(module_name, []):
                continue
            if issubclass(obj, unittest.TestCase) and obj.__module__ == module.__name__:
                globals()[name] = obj
                __all__.append(name)


__all__ = []
_load_cam_tests()
